/* The paper work owns its input, normalized space and animation. */
(function(root){'use strict';
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),copy=x=>JSON.parse(JSON.stringify(x));
function validate(c){if(!c||!c.rest||!c.anchor||![c.rest.u,c.rest.v,c.anchor.u,c.anchor.v].every(x=>Number.isFinite(x)&&x>=.08&&x<=.92)||!Number.isFinite(c.delay)||c.delay<0||c.delay>2||!Number.isFinite(c.response)||c.response<.1||c.response>2)throw Error('紙の状態が範囲外です');return copy(c);}
class Paper{constructor(c){this.config=validate(c);this.reset();}reset(){this.x=this.config.rest.u;this.y=this.config.rest.v;this.vx=0;this.vy=0;this.time=0;this.held=false;}step(dt,p){this.held=!!p;if(p){this.time=0;}else this.time+=dt;const target=p||this.config.rest,k=1-Math.exp(-dt*12/this.config.response);if(p||this.time>=this.config.delay){this.x+=(target.u-this.x)*k;this.y+=(target.v-this.y)*k;}}}
if(typeof module!=='undefined'&&module.exports){module.exports={Paper,validate};return;}
const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d');let config={rest:{u:.28,v:.58},anchor:{u:.72,v:.38},delay:.3,response:.6},model=new Paper(config),pointer=null,editing=false,paused=false,bridge,w=1,h=1,last=0;
function restore(c){config=validate(c);model=new Paper(config);pointer=null;}
const screen=e=>{const r=canvas.getBoundingClientRect();return{u:clamp((e.clientX-r.left)/r.width,.08,.92),v:clamp((e.clientY-r.top)/r.height,.08,.92)};};
canvas.addEventListener('pointerdown',e=>{if(editing||pointer)return;canvas.setPointerCapture(e.pointerId);pointer={id:e.pointerId,...screen(e)};});canvas.addEventListener('pointermove',e=>{if(pointer?.id===e.pointerId)pointer={id:e.pointerId,...screen(e)};});const finish=e=>{if(pointer?.id===e.pointerId)pointer=null;};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);
function draw(){ctx.clearRect(0,0,w,h);ctx.fillStyle='#d4cfb9';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#b4b79e';ctx.lineWidth=1;for(let y=35;y<h;y+=35){ctx.beginPath();ctx.moveTo(20,y);ctx.lineTo(w-20,y);ctx.stroke();}const r=config.rest,a=config.anchor;ctx.strokeStyle='#7e8972';ctx.beginPath();ctx.moveTo(r.u*w,r.v*h);ctx.lineTo(model.x*w,model.y*h);ctx.stroke();ctx.fillStyle='#697d67';ctx.beginPath();ctx.arc(a.u*w,a.v*h,12,0,Math.PI*2);ctx.fill();ctx.save();ctx.translate(model.x*w,model.y*h);ctx.rotate((model.x-r.u)*.5);ctx.fillStyle='#b4a478';ctx.fillRect(-24,-20,48,40);ctx.strokeStyle='#847859';ctx.strokeRect(-24,-20,48,40);ctx.restore();ctx.fillStyle='#495b48';ctx.font='14px sans-serif';ctx.fillText(editing?'紙の始点と留め具を動かす':'紙をつまんで運び、離す',18,26);}
function loop(t){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;if(w!==r.width||h!==r.height){w=r.width;h=r.height;canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0);}if(!paused&&!editing)model.step(Math.min(.03,(t-last)/1000||.016),pointer);last=t;draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);
bridge=root.FeelBridge?.connect({play(){paused=false;},pause(v){paused=v;pointer=null;},reset(){model.reset();pointer=null;},getState:()=>copy(config),restoreState:restore,getEditableElements:()=>[{id:'rest',label:'紙の始点',type:'position',screen:{x:config.rest.u,y:config.rest.v}},{id:'anchor',label:'留め具',type:'position',screen:{x:config.anchor.u,y:config.anchor.v}},{id:'delay',label:'離してから待つ',type:'timing',min:0,max:2,step:.05,value:config.delay,unit:'秒'},{id:'response',label:'追従する時間',type:'timing',min:.1,max:2,step:.05,value:config.response,unit:'秒'}],beginEdit(id){editing=true;pointer=null;},applyEdit(id,change){const c=copy(config);if(['rest','anchor'].includes(id)){if(!change.point||![change.point.x,change.point.y].every(Number.isFinite))throw Error('位置が不正です');c[id]={u:clamp(change.point.x,.08,.92),v:clamp(change.point.y,.08,.92)};}else if(['delay','response'].includes(id))c[id]=change.value;else throw Error('編集対象がありません');restore(c);},endEdit(id){if(id===null)editing=false;},getComparisonInfo:()=> 'Aは離すと始点へ戻る。入力は紙の目標位置。'});
document.addEventListener('visibilitychange',()=>{paused=document.hidden;pointer=null;});
})(typeof window!=='undefined'?window:globalThis);
